#!/usr/bin/env bash
# Build the local PKCS#11 test material used by openfirma-keystore's integration
# tests: a SoftHSM token and an NSS shared DB, both holding the synthetic test
# signers (RSA + EC) generated by tools/gen-testcert.sh.
#
# Everything lives under $TESTDIR (default /tmp/opencode/keystores) so a reboot
# or cleanup wipes it; rerun this script to rebuild. Tests skip when material
# is absent. Requires: softhsm2-util, pkcs11-tool (opensc), pk12util, openssl.
set -euo pipefail
cd "$(dirname "$0")/.."
TESTDIR="${OPENFIRMA_KEYSTORE_TESTDIR:-/tmp/opencode/keystores}"
PIN=12345678
CERTS=testdata/certs

[ -f "$CERTS/signer-rsa.crt.der" ] || tools/gen-testcert.sh >/dev/null
mkdir -p "$TESTDIR/softhsm/tokens" "$TESTDIR/nssdb"

cat > "$TESTDIR/softhsm/softhsm2.conf" <<CONF
directories.tokendir = $TESTDIR/softhsm/tokens
objectstore.backend = file
log.level = ERROR
CONF
export SOFTHSM2_CONF="$TESTDIR/softhsm/softhsm2.conf" # SoftHSM honours SOFTHSM2_CONF, not SOFT_CONFIG

# Fresh token each run (slot IDs change; tests match by token label).
rm -rf "$TESTDIR/softhsm/tokens"
mkdir -p "$TESTDIR/softhsm/tokens"
softhsm2-util --init-token --free --label "openfirma test" \
  --pin "$PIN" --so-pin "$PIN" >/dev/null

P11=/usr/lib/softhsm/libsofthsm2.so
[ -e "$P11" ] || P11=$(find /usr/lib /usr/lib64 -name libsofthsm2.so | head -1)
openssl pkcs8 -topk8 -nocrypt -in "$CERTS/signer-rsa.key" -outform DER -out "$TESTDIR/rsa.pk8.der"
openssl pkcs8 -topk8 -nocrypt -in "$CERTS/signer-ec.key"  -outform DER -out "$TESTDIR/ec.pk8.der"
for pair in "0a:$CERTS/signer-rsa.crt.der:$TESTDIR/rsa.pk8.der:openfirma rsa" \
            "0b:$CERTS/signer-ec.crt.der:$TESTDIR/ec.pk8.der:openfirma ec"; do
  id=${pair%%:*}; rest=${pair#*:}; crt=${rest%%:*}; rest=${rest#*:}; key=${rest%%:*}; lbl=${rest##*:}
  pkcs11-tool --module "$P11" --login --pin "$PIN" \
    --write-object "$crt" --type cert --id "$id" --label "$lbl" >/dev/null
  pkcs11-tool --module "$P11" --login --pin "$PIN" \
    --write-object "$key" --type privkey --id "$id" --label "$lbl key" >/dev/null
done

# A third pair marked CKA_ALWAYS_AUTHENTICATE (pkcs11-tool's --always-auth):
# the shape a qualified card's non-repudiation key carries (and OpenSC's DNIe
# signing key with user consent). SoftHSM enforces it — C_Sign answers
# CKR_USER_NOT_LOGGED_IN until C_Login(CKU_CONTEXT_SPECIFIC) runs between
# C_SignInit and C_Sign — which is exactly what tests/pkcs11_always_auth.rs
# pins (finding A4).
pkcs11-tool --module "$P11" --login --pin "$PIN" \
  --write-object "$CERTS/signer-rsa.crt.der" --type cert \
  --id 0c --label "openfirma always-auth" >/dev/null
pkcs11-tool --module "$P11" --login --pin "$PIN" \
  --write-object "$TESTDIR/rsa.pk8.der" --type privkey \
  --id 0c --label "openfirma always-auth key" --always-auth >/dev/null

# Two DNIe-shaped pairs (finding A5): certificates carrying the exact issuer
# AutoFirma's SkipAuthDNIeFilter matches (cn=AC DNIE *, ou=DNIE, o=DIRECCION
# GENERAL DE LA POLICIA). One has keyUsage digitalSignature alone (the
# authentication certificate: it must be hidden by default and only signable
# by explicit alias); the other adds nonRepudiation (the signing twin that
# stays visible) — both shapes tests/dnie_filter.rs pins against SoftHSM.
# Generated fresh into $TESTDIR by tools/gen-dnie-pair.sh (openssl CLI).
tools/gen-dnie-pair.sh "$TESTDIR/dnie" >/dev/null
for pair in "0d:$TESTDIR/dnie/auth.crt.der:DNIE auth" \
            "0e:$TESTDIR/dnie/sign.crt.der:DNIE sign"; do
  id=${pair%%:*}; rest=${pair#*:}; crt=${rest%%:*}; lbl=${rest##*:}
  pkcs11-tool --module "$P11" --login --pin "$PIN" \
    --write-object "$crt" --type cert --id "$id" --label "$lbl" >/dev/null
done
pkcs11-tool --module "$P11" --login --pin "$PIN" \
  --write-object "$TESTDIR/dnie/marta.pk8" --type privkey \
  --id 0d --label "DNIE auth key" >/dev/null
pkcs11-tool --module "$P11" --login --pin "$PIN" \
  --write-object "$TESTDIR/dnie/marta.pk8" --type privkey \
  --id 0e --label "DNIE sign key" >/dev/null

# NSS shared DB (empty password) with the same signers as PKCS#12.
rm -f "$TESTDIR/nssdb"/*
for who in rsa ec; do
  case $who in
    rsa) name="PEREZ GARCIA, ANA - openfirma test"; k=signer-rsa;;
    ec)  name="LOPEZ RUIZ, CARLOS - openfirma test"; k=signer-ec;;
  esac
  openssl pkcs12 -export -out "$TESTDIR/$who.p12" -inkey "$CERTS/$k.key" \
    -in "$CERTS/$k.crt" -name "$name" -passout pass: \
    -keypbe PBE-SHA1-3DES -certpbe PBE-SHA1-3DES -macalg sha1
  pk12util -d "sql:$TESTDIR/nssdb" -i "$TESTDIR/$who.p12" -W '' >/dev/null
done

echo "PKCS#11 module: $P11"
echo "SOFTHSM2_CONF=$SOFTHSM2_CONF (token label 'openfirma test', PIN $PIN)"
echo "NSS DB: sql:$TESTDIR/nssdb (empty password)"
